<?php require __DIR__.'/../config/database.php';require __DIR__.'/../config/auth.php';require_role(['staff']);require_work_checkin($pdo);$msg=$err='';
if($_SERVER['REQUEST_METHOD']==='POST'){$pdo->beginTransaction();try{$pid=(int)$_POST['product_id'];$qty=(float)$_POST['qty'];if($qty<=0)throw new Exception('Quantity must be greater than zero.');$pdo->prepare("INSERT INTO production_collections(product_id,staff_user_id,qty,fish_weight_kg,note) VALUES(?,?,?,?,?)")->execute([$pid,$_SESSION['user']['id'],$qty,$_POST['fish_weight_kg']!==''?(float)$_POST['fish_weight_kg']:null,trim($_POST['note'])]);$pdo->prepare("UPDATE shop_products SET stock_qty=stock_qty+? WHERE id=?")->execute([$qty,$pid]);$pdo->commit();$msg='Collection saved and shop stock updated.';}catch(Throwable $e){$pdo->rollBack();$err=$e->getMessage();}}
$p=$pdo->query("SELECT * FROM shop_products WHERE status IN('active','draft') ORDER BY category,name")->fetchAll();$page_title='Production Collection';require __DIR__.'/../partials/header.php';?>
<div class="container py-4"><div class="hero-top mb-4"><h2>Production / Harvest Collection</h2><p class="mb-0">Add milk, fish, rice or other collected production. Selling price remains Manager-only.</p></div><?php if($msg):?><div class="alert alert-success"><?=$msg?></div><?php endif;?><?php if($err):?><div class="alert alert-danger"><?=$err?></div><?php endif;?><div class="cardx p-4"><form method="post"><div class="mb-3"><label>Shop Product</label><select class="form-select" name="product_id" required><?php foreach($p as $x):?><option value="<?=$x['id']?>"><?=htmlspecialchars($x['category'].' — '.$x['name'].' ('.$x['unit'].')')?></option><?php endforeach;?></select></div><div class="row g-3"><div class="col-md-6"><label>Collected Quantity</label><input class="form-control" type="number" step=".01" name="qty" required></div><div class="col-md-6"><label>Fish Weight / Size KG (optional)</label><input class="form-control" type="number" step=".01" name="fish_weight_kg"></div></div><div class="mt-3"><label>Note</label><textarea class="form-control" name="note"></textarea></div><button class="btn btn-success mt-3">Update Shop Stock</button></form></div></div>
